	protected static class AvailableRegistersTableModel : DefaultEnumeratedColumnTableModel<AvailableRegisterTableColumns, AvailableRegisterRow> {
		public AvailableRegistersTableModel(PluginTool tool) : base(tool, "Available Registers", typeof(AvailableRegisterTableColumns))
    {
		}

